"""Delivery of recovery links to the configured loopback mail endpoint.

The provider's response is treated as an opaque blob end to end: this module
never inspects it for structure beyond deciding success/failure from the
HTTP status. Whatever text the provider returns is stored verbatim and later
handed to :mod:`accountsvc.notice` unparsed.
"""
from __future__ import annotations

import dataclasses
import json
import urllib.error
import urllib.request
from typing import Optional


@dataclasses.dataclass(frozen=True)
class MailResult:
    success: bool
    receipt: str
    error: Optional[str] = None


class MailClient:
    def __init__(self, mail_endpoint: str, timeout: float = 5.0):
        self._mail_endpoint = mail_endpoint
        self._timeout = timeout

    def send_recovery_notification(self, recipient: str, recovery_token: str) -> MailResult:
        payload = json.dumps(
            {"recipient": recipient, "recovery_token": recovery_token}
        ).encode("utf-8")
        request = urllib.request.Request(
            self._mail_endpoint,
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self._timeout) as response:
                body = response.read().decode("utf-8", errors="replace")
                return MailResult(success=True, receipt=body, error=None)
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", errors="replace")
            return MailResult(
                success=False,
                receipt=body,
                error=f"http_{exc.code}",
            )
        except urllib.error.URLError as exc:
            return MailResult(success=False, receipt="", error=str(exc.reason))
        except OSError as exc:
            return MailResult(success=False, receipt="", error=str(exc))

"""Stable JSON encoding used for every API and CLI response.

Keys are sorted and separators are fixed so that byte-identical inputs always
produce byte-identical output, regardless of dict insertion order.
"""
from __future__ import annotations

import json
from typing import Any


def dumps(obj: Any) -> str:
    """Return the canonical JSON encoding of ``obj``."""

    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def dumps_pretty(obj: Any) -> str:
    """Return a human-readable but still key-sorted JSON encoding."""

    return json.dumps(obj, sort_keys=True, indent=2, ensure_ascii=True)


def loads(data: str | bytes) -> Any:
    return json.loads(data)

import unittest

from accountsvc.notice import account_id_from_retry_locator, encode_retry_locator


class NoticeContractTest(unittest.TestCase):
    """The starter retry functions and signatures must not change behavior:
    the request's authoritative account binding always wins.
    """

    def test_encode_retry_locator_returns_account_id(self) -> None:
        self.assertEqual(
            encode_retry_locator("provider|OTHER_ACCOUNT", "ACCOUNT_A"), "ACCOUNT_A"
        )

    def test_account_id_from_retry_locator_uses_fallback(self) -> None:
        self.assertEqual(
            account_id_from_retry_locator("ACCOUNT_A", "ACCOUNT_A"), "ACCOUNT_A"
        )
        # Even a locator naming a different account cannot override the
        # request's authoritative binding.
        self.assertEqual(
            account_id_from_retry_locator("ACCOUNT_B", "ACCOUNT_A"), "ACCOUNT_A"
        )


if __name__ == "__main__":
    unittest.main()

